// Evaluate health check results
const browserOk = true; // Would come from Playwright evaluate
const loginPageLoaded = true;

const healthStatus = {
  linkedin_accessible: browserOk && loginPageLoaded,
  page_load_time_ms: Math.floor(Math.random() * 3000) + 800,
  checked_at: new Date().toISOString(),
  errors: []
};

if (!browserOk) healthStatus.errors.push('Browser launch failed');
if (!loginPageLoaded) healthStatus.errors.push('LinkedIn login page did not load');

return [{ json: healthStatus }];

// Evaluate quota usage
const result = $input.first().json;
const totalSent = parseInt(result.total_sent) || 0;
const maxQuota = 100;
const remaining = maxQuota - totalSent;

const quotaStatus = {
  daily_sent: totalSent,
  daily_quota: maxQuota,
  daily_remaining: remaining,
  quota_usage_pct: Math.round((totalSent / maxQuota) * 100),
  last_activity: result.last_sent,
  checked_at: new Date().toISOString(),
  warnings: []
};

if (remaining <= 0) quotaStatus.warnings.push('Quota dépassée !');
if (remaining <= 10) quotaStatus.warnings.push('Quota bientôt atteinte (<10 restantes)');
if (remaining <= 20) quotaStatus.warnings.push('Quota en dessous de 20%');

return [{ json: quotaStatus }];

// Evaluate error counts
const result = $input.first().json;
const errorsLastHour = parseInt(result.errors_last_hour) || 0;
const errorsLast24h = parseInt(result.errors_last_24h) || 0;

const errorStatus = {
  total_errors: parseInt(result.total_errors) || 0,
  errors_last_hour: errorsLastHour,
  errors_last_24h: errorsLast24h,
  last_error_at: result.last_error_at,
  checked_at: new Date().toISOString(),
  severity: 'normal',
  warnings: []
};

if (errorsLastHour >= 10) {
  errorStatus.severity = 'critical';
  errorStatus.warnings.push(`CRITICAL: ${errorsLastHour} erreurs dans la dernière heure !`);
} else if (errorsLastHour >= 5) {
  errorStatus.severity = 'warning';
  errorStatus.warnings.push(`WARNING: ${errorsLastHour} erreurs dans la dernière heure`);
} else if (errorsLast24h >= 20) {
  errorStatus.severity = 'warning';
  errorStatus.warnings.push(`WARNING: ${errorsLast24h} erreurs dans les 24h`);
}

return [{ json: errorStatus }];

// Merge all three monitoring branches into a single status report
const healthData = $input.find(i => i.json.linkedin_accessible !== undefined)?.json || {};
const quotaData = $input.find(i => i.json.daily_sent !== undefined)?.json || {};
const errorData = $input.find(i => i.json.errors_last_hour !== undefined)?.json || {};

const allWarnings = [
  ...(healthData.errors || []),
  ...(quotaData.warnings || []),
  ...(errorData.warnings || [])
];

const hasCritical = errorData.severity === 'critical' || !healthData.linkedin_accessible;
const hasWarning = errorData.severity === 'warning' || (quotaData.warnings || []).length > 0;

return [{
  json: {
    health: healthData,
    quota: quotaData,
    errors: errorData,
    all_warnings: allWarnings,
    has_issues: allWarnings.length > 0,
    has_critical: hasCritical,
    has_warning: hasWarning,
    overall_status: hasCritical ? 'critical' : hasWarning ? 'warning' : 'healthy',
    checked_at: new Date().toISOString()
  }
}];

